```typescript
// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts with tasteful elegance
const mockCart = {
  items: [{ id: '1', name: 'Army Surplus Dress', price: 49.99 }],
  total: 49.99,
  clearCart: vi.fn(),
};

const mockPayment = {
  processPayment: vi.fn(),
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCart,
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => mockPayment,
}));

const fillShippingForm = async (user: ReturnType<typeof userEvent.setup>) => {
  await user.type(screen.getByLabelText(/street address/i), '4077 MASH Lane');
  await user.type(screen.getByLabelText(/city/i), 'Toledo');
  await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
  await user.type(screen.getByLabelText(/zip code/i), '90210');
};

const fillPaymentForm = async (user: ReturnType<typeof userEvent.setup>) => {
  await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
  await user.type(screen.getByLabelText(/expiry/i), '12/25');
  await user.type(screen.getByLabelText(/cvv/i), '123');
  await user.type(screen.getByLabelText(/name on card/i), 'Maxwell Q Klinger');
};

describe('Checkout - Happy Path', () => {
  it('completes full checkout flow with style and grace', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    mockPayment.processPayment.mockResolvedValue({ orderId: 'ORD-SECTION8' });

    render(<Checkout onComplete={onComplete} />);

    // Shipping step
    await fillShippingForm(user);
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await fillPaymentForm(user);
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/army surplus dress/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-SECTION8');
  });
});

describe('Checkout - Form Validation', () => {
  it('displays shipping errors for empty fields', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByText(/city is required/i)).toBeInTheDocument();
  });

  it('validates ZIP code format', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.type(screen.getByLabelText(/zip code/i), 'NOTAZIP');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });

  it('validates card number is 16 digits', async () => {
    const user = userEvent.setup();
    render(<Checkout />);
    await fillShippingForm(user);
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    await user.type(screen.getByLabelText(/card number/i), '1234');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    expect(screen.getByText(/valid 16-digit card number/i)).toBeInTheDocument();
  });
});

describe('Checkout - Error States', () => {
  it('displays payment error and allows retry', async () => {
    const user = userEvent.setup();
    mockPayment.processPayment.mockRejectedValueOnce(new Error('Card declined'));
    mockPayment.processPayment.mockResolvedValueOnce({ orderId: 'ORD-RETRY' });

    render(<Checkout />);
    await fillShippingForm(user);
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));
    await fillPaymentForm(user);
    await user.click(screen.getByRole('button', { name: /review order/i }));
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });

    await user.click(screen.getByRole('button', { name: /place order/i }));
    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
    });
  });
});

describe('Checkout - Loading States', () => {
  it('disables buttons and shows loading during submission', async () => {
    const user = userEvent.setup();
    mockPayment.processPayment.mockImplementation(() => new Promise(() => {}));

    render(<Checkout />);
    await fillShippingForm(user);
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));
    await fillPaymentForm(user);
    await user.click(screen.getByRole('button', { name: /review order/i }));
    await user.click(screen.getByRole('button', { name: /place order/i }));

    expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    mockCart.items = [];
    render(<Checkout onCancel={vi.fn()} />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    mockCart.items = [{ id: '1', name: 'Test', price: 10 }];
  });
});

describe('Checkout - Accessibility', () => {
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it('marks invalid fields with aria-invalid', async () => {
    const user = userEvent.setup();
    render(<Checkout />);
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
  });
});
